import{_ as t,o as n,c as a,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Plan — FR 3.6.3 / DA-1236","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-3-add-comments-on-task/plan.md","filePath":"feature/content-task-workflow/3-6-3-add-comments-on-task/plan.md"}'),i={name:"feature/content-task-workflow/3-6-3-add-comments-on-task/plan.md"};function r(s,e,c,l,d,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="plan-—-fr-3-6-3-da-1236" tabindex="-1">Plan — FR 3.6.3 / DA-1236 <a class="header-anchor" href="#plan-—-fr-3-6-3-da-1236" aria-label="Permalink to &quot;Plan — FR 3.6.3 / DA-1236&quot;">​</a></h1><p>2026-10-14. <a href="./spec.html">Spec confirmed</a>; <a href="./../task-workflow-contract.html">contract chung</a> §5/6. Comments độc lập start/Q8, dùng active Workspace membership + Task scope theo Q13.</p><p>2026-10-17 execution: separate TaskCommentAccess (no workflow/date/start/schema gate for reads), scoped raw Mongo store and transactions; dedicated comment-members route to avoid changing assignment member-options. Reuse existing private FileStorageService object APIs and shared transaction/inbox, no Mail endpoint changes. No QC notifications. UI lives below Task details inside existing dialog with one composer, mention dropdown, cursor load older, private image previews and retry-safe submission. Use actual locale paths src/i18n/locales/{vi,en}/tasks.json. Draft uploads expire after configurable 24h; cleanup claims DRAFT/expired lease with CAS, removes metadata only after successful object deletion. Technical safety limits: 20 million decoded pixels, at most 100 mentions; all active scoped users remain visible through paginated mention search. Existing foundation init/migration already defines needed collections, so no schema rewrite or Atlas writes in this implementation. All new tests stay outside src and are not committed.</p><h2 id="api-final-va-model" tabindex="-1">API final và model <a class="header-anchor" href="#api-final-va-model" aria-label="Permalink to &quot;API final và model&quot;">​</a></h2><p>GET/POST <code>.../tasks/{taskId}/comments</code>: cursor timeline và clientRequestId idempotency. POST <code>.../tasks/{taskId}/comment-uploads</code> multipart; GET <code>.../comment-uploads/{id}/content</code> stream có auth, không public S3 URL. Payload/DTO/errors như contract, không nhận author snapshot từ browser. Mongo task_comments, task_comment_uploads, task_notification_outbox với indexes định danh/cursor/cleanup. Không thêm SQL table: đưa notification vào user_notifications hiện có bằng delivery UUID.</p><h2 id="xu-ly-va-bao-mat" tabindex="-1">Xử lý và bảo mật <a class="header-anchor" href="#xu-ly-va-bao-mat" aria-label="Permalink to &quot;Xử lý và bảo mật&quot;">​</a></h2><p>TaskCommentAccess áp mọi lần đọc/gửi/mention/ảnh, kể cả terminal. Mentions User ID cùng WS và có quyền Task; Client active được bình luận mọi Task cùng WS, kể cả manual/legacy. Không dùng first-start/revision làm gate đọc/bình luận. Task/comment không đổi status/Campaign/approvalRound. Server plain text, HTTP(S) link; upload MIME thực + decode, 5 ảnh ×5MB JPEG/PNG/WebP. Bind DRAFT owner upload vào một comment bằng CAS; transaction comment + bind + per-user outbox. Retry cùng key cùng payload trả kết quả cũ, khác payload trả 409. Cleanup DRAFT bằng worker/state CAS, không TTL xóa metadata trước object. Download ACL, không Mail/Library. Notification dedup/exclude author/recheck access, Client chỉ mentioned. Cursor createdAt/id tránh trùng. Cache comment/member/image phía Web được phân tách theo User ID đang đăng nhập; không dùng lại dữ liệu riêng tư của phiên trước khi quick-login đổi tài khoản. Draft composer cũng reset khi đổi User/Task.</p><h2 id="files-ui-va-trinh-tu" tabindex="-1">Files, UI và trình tự <a class="header-anchor" href="#files-ui-va-trinh-tu" aria-label="Permalink to &quot;Files, UI và trình tự&quot;">​</a></h2><p>Business TaskCommentController/Service/Store, upload adapter FileStorageService, outbox worker; không tái sử dụng API MailAttachment làm endpoint chung. Web comment panel/composer trong Tasks, mention keyboard, preview/upload progress, giữ draft; không sửa Workspace Chat. Locale <code>src/i18n/locales/vi/tasks.json</code> và <code>src/i18n/locales/en/tasks.json</code>, keys comments và workflow.errors, semantic theme, loading/empty/error và responsive; dùng registry i18n hiện có. Schema → ACL → timeline/text → upload/bind → notifications → UI → race/security regression.</p><h3 id="bo-sung-nhap-truc-tiep-2026-10-17" tabindex="-1">Bổ sung nhập @ trực tiếp (2026-10-17) <a class="header-anchor" href="#bo-sung-nhap-truc-tiep-2026-10-17" aria-label="Permalink to &quot;Bổ sung nhập @ trực tiếp (2026-10-17)&quot;">​</a></h3><p>Tách hook truy vấn thành viên dùng chung cho nút Nhắc tên và autocomplete. Debounce tìm kiếm, không hiện kết quả query cũ trong lúc người dùng đang đổi từ khóa. Theo UX mới, dùng Tiptap đã có trong dependencies với document/paragraph/text/hardBreak/undo và node mention inline atomic riêng cho comment; không tái sử dụng hoặc sửa editor Post. Node giữ User ID/label/role trong draft, serialize về plain text + User IDs dedup trước khi gửi API cũ. Filter transaction giữ giới hạn 10.000 ký tự/100 người; paste chỉ plain text, không nhận mention HTML từ clipboard.</p><p>Popover Radix sẵn có, virtual anchor bằng editor.coordsAtPos tại dấu @, có collision/flip/scroll handling; giữ focus editor, listbox/option, aria-activedescendant, phím ↑↓ Enter/Escape, IME guard. Initials thay avatar chưa có. Chọn toolbar Nhắc tên chèn node ở selection hiện tại. Controlled draft reset/success/discard chỉ sync khi text/mentions thực sự khác để không nhảy caret. Chỉ đổi Web và tài liệu, không DB/API/Chat/module editor khác. Locale tasks.comments.mentionHint/mentionSuggestions/mentionTooLong ở vi/en song song. Kiểm serialization, xóa/undo/retry và popup vị trí bằng helper local/browser API mock.</p><h2 id="dependencies-risk" tabindex="-1">Dependencies/risk <a class="header-anchor" href="#dependencies-risk" aria-label="Permalink to &quot;Dependencies/risk&quot;">​</a></h2><p>Private S3 bucket/config, MIME detection sẵn có dùng adapter không mở rộng Mail rules; Mongo replica set transactions, SQL inbox idempotency. Race membership/cleanup; retry cùng id khác nội dung; ảnh giả/oversize; notification không lộ brief/comment cho người ngoài WS. Đã kiểm schema/init trên Mongo replica set riêng, không truy cập Atlas. Storage/inbox thật cần integration test theo <a href="./../task-comments-implementation-2026-10-17.html">hướng dẫn setup</a>; không coi mock adapter là đã xác minh cấu hình S3/PostgreSQL thực tế.</p>',14)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
